CREATE TABLE ds_t(id int PRIMARY KEY, v int);
CREATE TABLE ds_z(x int, y int);
CREATE TABLE ds_zero(x int);
INSERT INTO ds_t VALUES (1, 10), (2, 20), (3, 30);
INSERT INTO ds_z VALUES (1, 5), (3, 7);
INSERT INTO ds_zero VALUES (0);
UPDATE ds_t SET v = (SELECT 1/x FROM ds_zero) WHERE id > 100;
UPDATE ds_t SET v = CASE WHEN id > 100 THEN (SELECT 1/x FROM ds_zero) ELSE v END;
UPDATE ds_t SET v = v WHERE id > 100 AND v IN (SELECT 1/x FROM ds_zero);
UPDATE ds_t SET v = v WHERE id > 100 AND (SELECT 1/x FROM ds_zero) > 0;
UPDATE ds_t SET v = v WHERE id / 0 > 1 AND (SELECT count(*) FROM ds_zero) > 5;
DELETE FROM ds_t WHERE id > 100 AND v IN (SELECT 1/x FROM ds_zero);
DELETE FROM ds_t WHERE id > 100 AND EXISTS (SELECT 1/x FROM ds_zero WHERE 1/x > 0);
DELETE FROM ds_t WHERE id / 0 > 1 AND (SELECT count(*) FROM ds_zero) > 5;
INSERT INTO ds_t SELECT 9, 9 WHERE false AND 1 = ANY (SELECT 1/x FROM ds_zero);
INSERT INTO ds_t SELECT 9, 9 WHERE 1 = ANY (SELECT 1/x FROM ds_zero) AND false;
INSERT INTO ds_t SELECT 9, CASE WHEN false THEN (SELECT 1/x FROM ds_zero) END;
INSERT INTO ds_t VALUES (10, CASE WHEN false THEN (SELECT 1/x FROM ds_zero) END);
UPDATE ds_t SET v = (SELECT 1/x FROM ds_zero) FROM ds_z WHERE false;
SELECT 1 WHERE 1 = ANY (SELECT 1/x FROM ds_zero) AND false;
SELECT CASE WHEN false THEN (SELECT 1/x FROM ds_zero) END;
SELECT 1 FROM ds_t WHERE (SELECT 1/x FROM ds_zero) > 0 LIMIT 0;
SELECT * FROM ds_t ORDER BY id;
BEGIN;
UPDATE ds_t SET v = CASE WHEN id = 3 THEN (SELECT sum(v) FROM ds_t) ELSE v + 100 END;
SELECT * FROM ds_t ORDER BY id;
INSERT INTO ds_t SELECT g, CASE WHEN g = 6 THEN (SELECT count(*) FROM ds_t) END FROM generate_series(4, 6) g;
INSERT INTO ds_t VALUES (7, 0), (8, (SELECT count(*) FROM ds_t));
SELECT * FROM ds_t ORDER BY id;
UPDATE ds_t SET v = (SELECT max(v) FROM ds_t WHERE id < 3) WHERE id > 5 RETURNING *;
ROLLBACK;
BEGIN;
UPDATE ds_t SET v = (SELECT y FROM ds_z WHERE ds_z.x = ds_t.id) WHERE EXISTS (SELECT 1 FROM ds_z WHERE ds_z.x = ds_t.id) RETURNING *;
UPDATE ds_t SET v = v + 1 WHERE v > (SELECT y - 1 FROM ds_z WHERE ds_z.x = ds_t.id) RETURNING *;
DELETE FROM ds_t WHERE id IN (SELECT x FROM ds_z WHERE y + 1 = ds_t.v) RETURNING *;
ROLLBACK;
BEGIN;
UPDATE ds_t SET v = s.y FROM ds_z s WHERE s.x = ds_t.id AND ds_t.v > (SELECT min(y) FROM ds_z WHERE x = s.x) RETURNING ds_t.*;
UPDATE ds_t SET v = (SELECT y + s.y FROM ds_z WHERE x = s.x) FROM ds_z s WHERE s.x = ds_t.id RETURNING ds_t.*;
DELETE FROM ds_t USING ds_z s WHERE s.x = ds_t.id AND EXISTS (SELECT 1 FROM ds_z WHERE x = s.x AND y * 2 = ds_t.v) RETURNING ds_t.*;
ROLLBACK;
INSERT INTO ds_t VALUES (3, 0) ON CONFLICT (id) DO UPDATE SET v = (SELECT count(*) FROM ds_t) WHERE (SELECT count(*) FROM ds_z) > 1 RETURNING *;
INSERT INTO ds_t VALUES (4, 0), (3, 0) ON CONFLICT (id) DO UPDATE SET v = (SELECT count(*) FROM ds_t) RETURNING *;
INSERT INTO ds_t VALUES (5, 0) ON CONFLICT (id) DO UPDATE SET v = (SELECT 1/x FROM ds_zero) RETURNING *;
CREATE VIEW ds_v AS SELECT * FROM ds_t;
CREATE FUNCTION ds_vu() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE ds_t SET v = NEW.v WHERE id = OLD.id; RETURN NEW; END $$;
CREATE TRIGGER ds_vu INSTEAD OF UPDATE ON ds_v FOR EACH ROW EXECUTE FUNCTION ds_vu();
UPDATE ds_v SET v = (SELECT max(y) FROM ds_z) + ds_v.id WHERE id < 3;
UPDATE ds_v SET v = (SELECT y FROM ds_z WHERE x = ds_v.id) WHERE id IN (1, 3);
UPDATE ds_v SET v = s.y FROM ds_z s WHERE s.x = ds_v.id AND (SELECT count(*) FROM ds_z) = 2;
SELECT * FROM ds_t ORDER BY id;
